mapper.sql:
WHERE a.del_flag = '0'
AND a.channel_id = #{channelId}
AND a.status = #{status}
AND a.create_by = #{createBy}

    AND (a.title LIKE CONCAT('%', #{keyword}, '%')
      OR a.summary LIKE CONCAT('%', #{keyword}, '%')
      OR a.content_html LIKE CONCAT('%', #{keyword}, '%'))

AND a.create_time >= #{startTime}
AND a.create_time <= #{endTime}

mapper.select:
SELECT FROM cms_article a
INNER JOIN cms_article_tag at ON at.article_id = a.id AND at.tag_id = #{tagId}
ORDER BY a.sort_order DESC, a.id DESC

SELECT FROM cms_article a
INNER JOIN cms_article_tag at ON at.article_id = a.id AND at.tag_id = #{tagId}
WHERE a.del_flag = '0' AND a.status = 'PUBLISHED' AND a.channel_id = #{channelId}
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.summary LIKE CONCAT('%', #{keyword}, '%') OR a.content_html LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.sort_order DESC, a.published_at DESC, a.id DESC

SELECT article_id, tag_id FROM cms_article_tag
WHERE article_id IN
#{id}
